import React, { useEffect, useState } from "react";
import { Alert, Box, LinearProgress, Typography } from "@mui/material";
import {
  computePostAssignmentSla,
  formatDateTime,
  formatDurationMinutes,
  getSlaLevelLabel,
} from "../utils/slaKpi";

const SlaTimerBanner = ({
  assignedAt,
  priority,
  resolvedAt,
  compact = false,
}) => {
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    if (resolvedAt) return undefined;
    const id = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(id);
  }, [resolvedAt]);

  const sla = computePostAssignmentSla({
    assignedAt,
    priority,
    resolvedAt,
    now,
  });

  const severity =
    sla.state === "resolved_met" || sla.state === "active"
      ? "success"
      : sla.state === "unassigned" || sla.state === "unknown"
        ? "info"
        : "error";

  const progress =
    sla.slaMinutes && sla.assignedAt && !resolvedAt
      ? Math.min(
          100,
          Math.max(
            0,
            ((now - new Date(sla.assignedAt).getTime()) /
              (sla.slaMinutes * 60 * 1000)) *
              100,
          ),
        )
      : sla.resolvedAt
        ? sla.breached
          ? 100
          : Math.min(
              100,
              ((sla.resolutionFromAssignmentMinutes || 0) / sla.slaMinutes) *
                100,
            )
        : 0;

  return (
    <Alert severity={severity} sx={{ mb: compact ? 1 : 2 }}>
      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
        Post-assignment SLA ({getSlaLevelLabel(priority)} —{" "}
        {sla.slaMinutes ? formatDurationMinutes(sla.slaMinutes) : "—"} target)
      </Typography>
      <Typography variant="body2">{sla.message}</Typography>
      {assignedAt && (
        <Box sx={{ mt: 1, fontSize: "0.8rem", color: "text.secondary" }}>
          <div>Assigned: {formatDateTime(assignedAt)}</div>
          {sla.deadlineAt && (
            <div>Deadline: {formatDateTime(sla.deadlineAt)}</div>
          )}
          {resolvedAt && <div>Resolved: {formatDateTime(resolvedAt)}</div>}
          {sla.resolutionFromAssignmentMinutes != null && (
            <div>
              Time from assignment:{" "}
              {formatDurationMinutes(sla.resolutionFromAssignmentMinutes)}
            </div>
          )}
        </Box>
      )}
      {sla.slaMinutes && (
        <LinearProgress
          variant="determinate"
          value={progress}
          color={sla.breached ? "error" : "primary"}
          sx={{ mt: 1.5, height: 6, borderRadius: 1 }}
        />
      )}
    </Alert>
  );
};

export default SlaTimerBanner;
